entity = {'loan_id': 'bigint', 'amount': 'decimal(18,0)', 'rate': 'decimal(7,4)', 'status': 'varchar(20)'}
schema = {'loan_id': 'bigint', 'amount': 'decimal(18,0)', 'status': 'varchar(20)'}
def validate(entity, schema):
    for col, typ in entity.items():
        if col not in schema:
            raise SystemExit(f'시작 거부: 표에 {col} 칸이 없다 (엔티티는 {typ})')
        if schema[col] != typ:
            raise SystemExit(f'시작 거부: {col} 형이 다르다')
    print('검증 통과 -> 서버 시작')
validate(schema, schema)
try:
    validate(entity, schema)
except SystemExit as e:
    print(e)
# 검증 통과 -> 서버 시작
# 시작 거부: 표에 rate 칸이 없다 (엔티티는 decimal(7,4))

def drain(burst, tps):
    sec, left, waits = 0, burst, []
    while left > 0:
        sec += 1
        sent = min(tps, left); left -= sent
        waits += [sec] * sent
    return sec, max(waits), sum(waits) / len(waits)
for tps in (50, 100):
    s, mx, avg = drain(3000, tps)
    print(f'요청 3,000건 · 기관 한도 {tps} TPS -> {s}초에 다 나감, 최대 대기 {mx}초, 평균 {avg:.1f}초')
# 요청 3,000건 · 기관 한도 50 TPS -> 60초에 다 나감, 최대 대기 60초, 평균 30.5초
# 요청 3,000건 · 기관 한도 100 TPS -> 30초에 다 나감, 최대 대기 30초, 평균 15.5초
